package com.jnapanam.sportszone.loyalty.repository;import com.jnapanam.sportszone.loyalty.model.LoyaltyWallet;import java.util.UUID;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import jakarta.persistence.LockModeType;public interface LoyaltyWalletRepository extends JpaRepository<LoyaltyWallet,UUID>{@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select w from LoyaltyWallet w where w.userId=:id")java.util.Optional<LoyaltyWallet>findLocked(@Param("id")UUID id);}
